/* Keep the surrounding controls visible; the terminal takes the remaining space. */
.theme-toggle {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--panel);
  color: var(--text);
  font-size: 11px;
  white-space: nowrap;
}
.theme-toggle:hover { border-color: var(--green); }
#theme-icon { font-size: 16px; line-height: 18px; }
:root[data-theme="light"] {
  color-scheme: light;
  --page: #f1f4ed;
  --panel: #eaf0e5;
  --line: #ccd6c6;
  --text: #26352d;
  --muted: #617166;
  --green: #356b35;
  --terminal: #fbfcf8;
}
[data-theme="light"] .brand-mark,
[data-theme="light"] .primary { color: #f7fbf2; }
[data-theme="light"] .primary:hover { background: #2a572b; }
[data-theme="light"] .actions button:hover { background: #dbe5d6; }
[data-theme="light"] .terminal-card { box-shadow: 0 22px 80px #233b1910; }
[data-theme="light"] .terminal-footer { border-color: var(--line); }
[data-theme="light"] .meta-divider { color: #9ca996; }
[data-theme="light"] kbd { background: #e7ede2; border-color: #bac9b4; }
[data-theme="light"] .notice { background: #e3eddb; border-color: #a8bda0; }
[data-theme="light"] dialog { background: var(--terminal); border-color: var(--line); }
[data-theme="light"] .xterm .xterm-viewport { scrollbar-color: #b3c1ac var(--terminal); }

body {
  height: 100vh;
  height: 100dvh;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.topbar { flex-shrink: 0; }
main {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.heading, .bottom { flex-shrink: 0; }
.terminal-card {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.toolbar, .terminal-footer { flex-shrink: 0; }
#terminal {
  flex: 1;
  height: auto;
  min-height: 0;
  overflow: hidden;
}
@media (max-height: 600px) {
  .topbar { height: 52px; }
  main { padding-top: 12px; padding-bottom: 10px; }
  .heading { margin-bottom: 12px; }
  h1 { font-size: 24px; }
  .heading p { margin-top: 4px; }
  .toolbar, .tab { height: 40px; }
  #terminal { padding-top: 8px; padding-bottom: 8px; }
  .terminal-footer { height: 26px; }
  .bottom { margin-top: 10px; }
}

.terminal-layout { display: flex; flex: 1; min-height: 0; }
.terminal-main { display: flex; flex-direction: column; flex: 1; min-width: 0; min-height: 0; }
.session-sidebar { width: 185px; flex-shrink: 0; background: var(--panel); border-left: 1px solid var(--line); display: flex; flex-direction: column; min-height: 0; order: 1; }
.sidebar-heading { height: 50px; flex-shrink: 0; display: flex; align-items: center; justify-content: space-between; padding: 0 16px; font-size: 11px; color: var(--muted); border-bottom: 1px solid var(--line); }
#session-count { font: 10px monospace; border: 1px solid var(--line); border-radius: 4px; padding: 2px 5px; }
#session-list { overflow: auto; padding: 8px; scrollbar-width: thin; scrollbar-color: var(--line) var(--panel); }
.session-row { display: flex; align-items: center; border: 1px solid transparent; border-radius: 6px; margin-bottom: 4px; }
.session-row.active { background: var(--terminal); border-color: var(--line); box-shadow: inset 2px 0 var(--green); }
.session-select { background: transparent; color: var(--muted); display: flex; flex: 1; min-width: 0; flex-direction: column; align-items: flex-start; gap: 4px; padding: 10px; text-align: left; }
.session-row.active .session-select { color: var(--text); }
.session-name { font: 12px ui-monospace, SFMono-Regular, Consolas, monospace; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.session-state { font-size: 9px; color: var(--muted); }
.session-row[data-state="connected"] .session-state { color: var(--green); }
.session-close { background: transparent; color: var(--muted); border-radius: 4px; width: 25px; height: 25px; margin-right: 7px; flex-shrink: 0; font-size: 18px; }
.session-close:hover { color: var(--text); background: var(--line); }
.sidebar-empty { color: var(--muted); font-size: 11px; padding: 0 16px; }
.terminal-view { width: 100%; height: 100%; display: none; }
.terminal-view.active { display: block; }
.terminal-empty { height: 100%; display: grid; align-content: center; justify-items: center; gap: 12px; color: var(--muted); font-size: 12px; }
.empty-mark { font: 32px monospace; color: var(--green); }
.terminal-empty[hidden], .sidebar-empty[hidden] { display: none; }
.connection-bar { display: flex; align-items: center; gap: 12px; margin-bottom: 18px; flex-shrink: 0; font-size: 12px; }
.connection-bar label, #hosts-status { color: var(--muted); }
.connection-bar select { min-width: 180px; max-width: 340px; flex: 1; background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 6px; padding: 9px 12px; font: inherit; }
.connection-bar select:focus-visible { outline: 2px solid var(--green); outline-offset: 2px; }
#refresh-hosts { color: var(--text); background: var(--panel); border: 1px solid var(--line); border-radius: 6px; padding: 9px 12px; font: inherit; }
#refresh-hosts:hover { border-color: var(--green); }
.tab { min-width: 0; }
#tab-title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 250px; }
.actions { flex-shrink: 0; }
.terminal-footer > span:first-child { min-width: 0; }
#identity { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@media (max-height: 600px) { .sidebar-heading { height: 40px; } }
@media (max-width: 700px) {
  .connection-bar { gap: 8px; flex-wrap: wrap; margin-bottom: 12px; font-size: 11px; }
  .connection-bar select { min-width: 0; max-width: none; padding: 8px; }
  #hosts-status { flex-basis: 100%; }
  #refresh-hosts { padding: 8px; }
  #tab-title { max-width: 100px; }
  .terminal-layout { flex-direction: column; }
  .session-sidebar { width: auto; border-left: 0; border-bottom: 1px solid var(--line); flex-shrink: 0; order: -1; }
  .sidebar-heading, .sidebar-empty { display: none; }
  #session-list { display: flex; gap: 6px; padding: 6px; }
  .session-row { flex: 0 0 116px; margin: 0; }
  .session-select { padding: 6px 8px; gap: 2px; }
  .session-close { margin-right: 4px; }
}
